{
  "app": {
    "name": "anarlog",
    "one_sentence": "The open-source AI meeting notetaker. Local-first. Privacy-first. Yours to fork.",
    "inspired_by": null
  },
  "core_loop": "Open it. Join a meeting. anarlog records, transcribes locally, and saves your notes as markdown on disk. Bring your own LLM (OpenAI, Anthropic, Gemini, OpenRouter, Ollama, LM Studio, anything OpenAI-compatible).",
  "screens": [
    {
      "id": "main",
      "name": "Main Meeting Notetaker",
      "purpose": "Record, transcribe, and save meeting notes locally as Markdown files with user-chosen LLM summarization.",
      "primary_actions": [
        "Start recording",
        "Stop recording",
        "Save note as .md",
        "Select LLM provider"
      ]
    }
  ],
  "rust_commands": [
    {
      "name": "save_item",
      "purpose": "Persist a meeting note as a local Markdown file on disk.",
      "async": true,
      "input": {},
      "output": {}
    }
  ],
  "data_model": {
    "tables": [
      {
        "name": "notes",
        "fields": [
          {
            "name": "id",
            "type": "string"
          },
          {
            "name": "content",
            "type": "string"
          },
          {
            "name": "filepath",
            "type": "string"
          }
        ]
      }
    ]
  },
  "mvp_plan": {
    "milestones": [
      {
        "week": 1,
        "tasks": [
          "Implement local audio capture and on-device transcription",
          "Integrate OpenAI-compatible LLM interface",
          "Save output as Markdown file to user-specified directory"
        ]
      }
    ]
  },
  "acceptance_tests": [
    "User can start/stop recording and see real-time transcription",
    "Meeting notes are saved as .md files readable by any text editor",
    "LLM provider can be switched without app restart"
  ],
  "open_questions": [
    "How to handle multi-language transcription robustly?",
    "What fallback exists if selected LLM is unreachable?"

